-- Update original payment copy only; preserve owner-written settings and all order records.
UPDATE store_settings SET data=json_set(data,'$.ordering','Choose your fragrance, enter your delivery details and review the total. Pay by direct UPI. Your order is confirmed as soon as the payment is verified.'),revision=revision+1 WHERE id=1 AND json_extract(data,'$.ordering')='Choose your fragrance, enter your delivery details and review the total. Pay by direct UPI or through Razorpay. Your order is confirmed as soon as the payment is verified.';
UPDATE store_settings SET data=json_set(data,'$.payment','Pay by direct UPI, with no added payment fee. Direct UPI orders are confirmed once we verify the payment. For cancellations or returns, contact us with your order reference.'),revision=revision+1 WHERE id=1 AND json_extract(data,'$.payment')='Pay by direct UPI or through Razorpay, with no added payment fee. Direct UPI orders are confirmed once we verify the payment. For cancellations or returns, contact us with your order reference.';
-- The FAQ is replaced only when it still equals the whole launch value written by 0008, so an owner-edited FAQ is never touched.
UPDATE store_settings SET data=json_set(data,'$.faq','Are prices and stock up to date?|Yes for anything you can add to your bag; checkout rechecks the price and stock before you pay. Community offers show dated seller quotes, so confirm the current price, availability and terms with us.
What is a decant?|A smaller amount transferred from the original bottle into a separate atomiser. The photo shows the original bottle for reference, not the decant packaging.
Does adding to my bag reserve stock?|No. Your bottles are held once you place an order at checkout, and released if payment is not completed in time.
How do delivery and payment work?|Delivery charges are shown at checkout before you pay. Pay by direct UPI; there is no added payment fee.'),revision=revision+1 WHERE id=1 AND json_extract(data,'$.faq')='Are prices and stock up to date?|Yes for anything you can add to your bag; checkout rechecks the price and stock before you pay. Community offers show dated seller quotes, so confirm the current price, availability and terms with us.
What is a decant?|A smaller amount transferred from the original bottle into a separate atomiser. The photo shows the original bottle for reference, not the decant packaging.
Does adding to my bag reserve stock?|No. Your bottles are held once you place an order at checkout, and released if payment is not completed in time.
How do delivery and payment work?|Delivery charges are shown at checkout before you pay. Choose direct UPI or Razorpay; there is no added payment fee.';
